interface UpsertTable {
  table: string;
  columns: string[];
  conflictColumn: string;
  rows: Array<Array<string | number | Date | null>>;
}

async function upsertRows(client: PoolClient, table: UpsertTable): Promise<void> {
  const batchSize = 500;
  const updates = table.columns.filter((column) => column !== table.conflictColumn);
  for (let offset = 0; offset < table.rows.length; offset += batchSize) {
    const batch = table.rows.slice(offset, offset + batchSize);
    const values: Array<string | number | Date | null> = [];
    const tuples = batch.map((row) => {
      const placeholders = row.map((value) => {
        values.push(value);
        return `$${values.length}`;
      });
      return `(${placeholders.join(", ")})`;
    });
    const columns = table.columns.map((column) => `"${column}"`).join(", ");
    const set = updates.map((column) => `"${column}" = EXCLUDED."${column}"`).join(", ");
    const sql = `INSERT INTO "${table.table}" (${columns}) VALUES ${tuples.join(", ")}
      ON CONFLICT ("${table.conflictColumn}") DO UPDATE SET ${set}`;
    await client.query(sql, values);
  }
}

export async function importReferenceData(data: ReferenceData): Promise<{ riders: number; trips: number; payoutLines: number }> {
  const client = await pool.connect();
  try {
    await client.query("BEGIN");
    await upsertRows(client, {
      table: "riders",
      columns: ["rider_id", "name", "city", "joined_on"],
      conflictColumn: "rider_id",
      rows: [...data.riders.values()].map((rider) => [rider.riderId, rider.name, rider.city, rider.joinedOn]),
    });
    await upsertRows(client, {
      table: "trips",
      columns: ["trip_id", "rider_id", "started_at", "status", "distance_km", "surge_multiplier"],
      conflictColumn: "trip_id",
      rows: data.trips.map((trip) => [trip.tripId, trip.riderId, trip.startedAt, trip.status, trip.distanceKm, trip.surgeMultiplier]),
    });
    await upsertRows(client, {
      table: "payout_lines",
      columns: ["line_id", "payout_date", "rider_id", "line_type", "trip_id", "amount_rupees"],
      conflictColumn: "line_id",
      rows: data.payoutLines.map((line) => [line.lineId, line.payoutDate, line.riderId, line.lineType, line.tripId, line.amountRupees]),
    });
    await client.query("COMMIT");
    return { riders: data.riders.size, trips: data.trips.length, payoutLines: data.payoutLines.length };
  } catch (error) {
    await client.query("ROLLBACK");
    throw error;
  } finally {
    client.release();
  }
}
import { randomUUID } from "node:crypto";
import { Pool, PoolClient } from "pg";
import {
  appendInvestigationContext,
  InvestigationEvent,
  InvestigationTarget,
  investigateIssues,
} from "./claims.js";
import { decideClaimPaths } from "./decisions.js";
import {
  GroqMessageUnderstander,
  IssueUpdate,
  LanguageUnderstandingUnavailable,
  MessageUnderstanding,
  RecentMessage,
  sanitizeUnderstanding,
} from "../infrastructure/llm/groq-client.js";

export class MessageIdConflict extends Error {}
export class StoredMessageUnavailable extends Error {}
export class MessageUnderstandingUnavailable extends Error {}

interface StoredInboundMessage {
  rider_id: string;
  text: string;
  received_at: Date;
  reply: string | null;
  processing_status: string;
}

export async function receiveMessage(
  pool: Pool,
  understander: GroqMessageUnderstander,
  args: { messageId: string; riderId: string; text: string; receivedAt: Date },
): Promise<string> {
  const client = await pool.connect();
  try {
    await client.query("BEGIN");
    const inserted = await client.query(
      `INSERT INTO inbound_messages (message_id, rider_id, text, received_at, reply, processing_status)
       VALUES ($1, $2, $3, $4, NULL, 'processing')
       ON CONFLICT (message_id) DO NOTHING RETURNING message_id`,
      [args.messageId, args.riderId, args.text, args.receivedAt],
    );

    if (inserted.rowCount === 0) {
      const existing = await client.query<StoredInboundMessage>(
        `SELECT rider_id, text, received_at, reply, processing_status
         FROM inbound_messages WHERE message_id = $1 FOR UPDATE`,
        [args.messageId],
      );
      const stored = existing.rows[0];
      if (!stored) throw new StoredMessageUnavailable("A duplicate message could not be loaded.");
      if (stored.rider_id !== args.riderId || stored.text !== args.text || stored.received_at.getTime() !== args.receivedAt.getTime()) {
        throw new MessageIdConflict("message_id has already been used for different message content.");
      }
      if (stored.processing_status === "processed" && stored.reply !== null) {
        await client.query("COMMIT");
        return stored.reply;
      }
      if (stored.processing_status === "processing") {
        throw new StoredMessageUnavailable("The earlier copy of this message is still being processed.");
      }
      await client.query(
        `UPDATE inbound_messages SET processing_status = 'processing', reply = NULL WHERE message_id = $1`,
        [args.messageId],
      );
    } else {
      await addTrace(client, args.riderId, "message_in", "inbound_message", {
        message_id: args.messageId,
        text: args.text,
        received_at: args.receivedAt.toISOString(),
      }, null);
    }
    await client.query("COMMIT");
  } catch (error) {
    await client.query("ROLLBACK");
    throw error;
  } finally {
    client.release();
  }

  try {
    const { state, recentMessages } = await loadContext(pool, args.riderId, args.messageId);
    const modelResult = await understander.understand({
      riderId: args.riderId,
      text: args.text,
      receivedAt: args.receivedAt,
      existingIssues: modelIssueContext(state.issues),
      recentMessages,
    });
    const result = sanitizeUnderstanding(modelResult, {
      text: args.text,
      riderId: args.riderId,
      receivedAt: args.receivedAt,
    });
    const applied = applyUpdates(state, result, args.messageId, args.receivedAt);
    const investigation = await investigateIssues(pool, args.riderId, args.receivedAt, applied.targets);
    const decisions = await decideClaimPaths(pool, args.riderId, investigation.outcomes, {
      messageId: args.messageId,
      identityMismatch: result.identity_mismatch,
    });
    const updatedState = appendInvestigationContext(applied.state, decisions.outcomes);
    const reply = decisions.identityMismatchReply ?? (decisions.outcomes.length > 0
      ? decisions.outcomes.map((item) => item.reply).join(" ")
      : result.reply);
    await saveCompletedMessage(pool, args, result, reply, state, updatedState, [...investigation.events, ...decisions.events]);
    return reply;
  } catch (error) {
    await markFailed(pool, args.messageId, args.riderId,
      error instanceof LanguageUnderstandingUnavailable ? "language_understanding_unavailable" : "message_processing_failed");
    if (error instanceof LanguageUnderstandingUnavailable) {
      throw new MessageUnderstandingUnavailable("Message understanding is temporarily unavailable.", { cause: error });
    }
    throw error;
  }
}

interface ConversationState {
  issues: Record<string, unknown>[];
  [key: string]: unknown;
}

async function loadContext(pool: Pool, riderId: string, currentMessageId: string): Promise<{
  state: ConversationState;
  recentMessages: RecentMessage[];
}> {
  const [conversation, history] = await Promise.all([
    pool.query<{ state: unknown }>("SELECT state FROM conversations WHERE rider_id = $1", [riderId]),
    pool.query<{ received_at: Date; text: string; reply: string | null }>(
      `SELECT received_at, text, reply FROM inbound_messages
       WHERE rider_id = $1 AND message_id <> $2 AND processing_status = 'processed'
       ORDER BY received_at DESC, message_id DESC LIMIT 8`,
      [riderId, currentMessageId],
    ),
  ]);
  const rawState = conversation.rows[0]?.state;
  const stateObject = rawState && typeof rawState === "object" && !Array.isArray(rawState)
    ? rawState as Record<string, unknown> : {};
  const rawIssues = Array.isArray(stateObject.issues) ? stateObject.issues : [];
  return {
    state: { ...stateObject, issues: rawIssues.filter(isJsonObject) },
    recentMessages: history.rows.reverse().map((row) => ({
      received_at: row.received_at.toISOString(),
      rider_message: row.text,
      // Replies may contain deterministic payout amounts; keep them out of Groq context.
      agent_reply: "",
    })),
  };
}

function isJsonObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function modelIssueContext(issues: Record<string, unknown>[]): Record<string, unknown>[] {
  const allowed = [
    "issue_id", "issue_type", "summary", "trip_ids", "dates",
    "missing_information", "follow_up_question",
  ];
  return issues.map((issue) => Object.fromEntries(
    allowed.filter((key) => key in issue).map((key) => [key, issue[key]]),
  ));
}

function applyUpdates(
  state: ConversationState,
  result: MessageUnderstanding,
  messageId: string,
  receivedAt: Date,
): { state: ConversationState; targets: InvestigationTarget[] } {
  const issues = [...state.issues];
  const targets: InvestigationTarget[] = [];
  if (!result.identity_mismatch) {
    for (const update of result.updates) {
      const issue = issueState(update, receivedAt);
      if (update.action === "create" && update.issue_id === null) {
        const issueId = randomUUID();
        issues.push({ issue_id: issueId, ...issue });
        targets.push({ issueId, update });
      } else if (update.action === "update" && update.issue_id) {
        const index = issues.findIndex((existing) => existing.issue_id === update.issue_id);
        if (index >= 0) {
          issues[index] = { issue_id: update.issue_id, ...issue };
          targets.push({ issueId: update.issue_id, update });
        }
      }
    }
  }
  return {
    state: { ...state, issues, last_message_id: messageId, updated_at: receivedAt.toISOString() },
    targets,
  };
}

function issueState(update: IssueUpdate, receivedAt: Date): Record<string, unknown> {
  return {
    issue_type: update.issue_type,
    summary: update.summary,
    trip_ids: update.trip_ids,
    dates: update.dates,
    missing_information: update.missing_information,
    follow_up_question: update.follow_up_question,
    updated_at: receivedAt.toISOString(),
  };
}

async function saveCompletedMessage(
  pool: Pool,
  args: { messageId: string; riderId: string },
  result: MessageUnderstanding,
  reply: string,
  previousState: ConversationState,
  updatedState: ConversationState,
  investigationEvents: InvestigationEvent[],
): Promise<void> {
  const client = await pool.connect();
  try {
    await client.query("BEGIN");
    await client.query(
      `INSERT INTO conversations (rider_id, state) VALUES ($1, $2::jsonb)
       ON CONFLICT (rider_id) DO UPDATE SET state = EXCLUDED.state, updated_at = now()`,
      [args.riderId, JSON.stringify(updatedState)],
    );
    await client.query(
      `UPDATE inbound_messages SET reply = $2, processing_status = 'processed' WHERE message_id = $1`,
      [args.messageId, reply],
    );
    await addTrace(client, args.riderId, "tool_call", "groq_message_understanding", {
      message_id: args.messageId,
      active_issue_ids: previousState.issues.map((issue) => issue.issue_id ?? null),
    }, result);
    for (const event of investigationEvents) {
      await addTrace(client, args.riderId, event.type, event.name, event.input, event.output);
    }
    await addTrace(client, args.riderId, "decision", "conversation_context_updated", {
      message_id: args.messageId,
    }, updatedState);
    await addTrace(client, args.riderId, "reply", "rider_follow_up", null, reply);
    await client.query("COMMIT");
  } catch (error) {
    await client.query("ROLLBACK");
    throw error;
  } finally {
    client.release();
  }
}

async function markFailed(pool: Pool, messageId: string, riderId: string, errorCode: string): Promise<void> {
  const client = await pool.connect();
  try {
    await client.query("BEGIN");
    await client.query(
      `UPDATE inbound_messages SET processing_status = 'failed', reply = NULL WHERE message_id = $1`,
      [messageId],
    );
    await addTrace(client, riderId, "error", "message_understanding_failed", { message_id: messageId }, { error: errorCode });
    await client.query("COMMIT");
  } catch (error) {
    await client.query("ROLLBACK");
    throw error;
  } finally {
    client.release();
  }
}

async function addTrace(
  client: PoolClient,
  riderId: string,
  eventType: string,
  name: string,
  input: unknown,
  output: unknown,
): Promise<void> {
  await client.query(
    `INSERT INTO trace_events (rider_id, event_type, name, input_data, output_data)
     VALUES ($1, $2, $3, $4::jsonb, $5::jsonb)`,
    [riderId, eventType, name, input === null ? null : JSON.stringify(input), output === null ? null : JSON.stringify(output)],
  );
}

import { createHash, randomUUID } from "node:crypto";
import { Pool } from "pg";
import { istDate } from "../domain/payouts.js";
import { ClaimOutcome } from "./claims.js";

const AUTO_PAYMENT_CAP_RUPEES = 200;
const ACTIVE_PAYMENT_STATUSES = ["reserved", "processing", "succeeded", "paid", "completed"];

export interface DecisionEvent {
  type: "decision";
  name: string;
  input: unknown;
  output: unknown;
}

export interface DecisionResult {
  outcomes: ClaimOutcome[];
  events: DecisionEvent[];
  identityMismatchReply?: string;
}

function fingerprintFor(riderId: string, item: ClaimOutcome): string {
  const details = {
    rider_id: riderId,
    scope: item.scope,
    dates: [...new Set(item.assessments.map((assessment) => assessment.payoutDate))].sort(),
    trip_ids: [...new Set(item.assessments.flatMap((assessment) => assessment.tripId ? [assessment.tripId] : []))].sort(),
    unresolved_reason: item.assessments.length === 0 ? item.reason : null,
  };
  return createHash("sha256").update(JSON.stringify(details)).digest("hex");
}

function claimEvidence(item: ClaimOutcome, fingerprint: string): Record<string, unknown> {
  return {
    issue_id: item.issue_id,
    fingerprint,
    scope: item.scope,
    status: item.status,
    decision_path: item.decision_path,
    decision_reason: item.decision_reason,
    verified_owed_rupees: item.verified_owed_rupees ?? 0,
    decision_amount_rupees: item.decision_amount_rupees ?? null,
    assessments: item.assessments.map((assessment) => ({
      rider_id: assessment.riderId,
      scope: assessment.scope,
      trip_id: assessment.tripId,
      payout_date: assessment.payoutDate,
      expected_rupees: assessment.expectedRupees,
      historical_paid_rupees: assessment.historicalPaidRupees,
      shortfall_rupees: assessment.shortfallRupees,
      breakdown: assessment.breakdown,
    })),
  };
}

async function createPendingOpsItem(
  pool: Pool,
  args: { riderId: string; type: "approval" | "escalation"; amount: number | null; reason: string; fingerprint: string | null; claim: Record<string, unknown> },
): Promise<{ id: string; created: boolean }> {
  const client = await pool.connect();
  try {
    await client.query("BEGIN");
    if (args.fingerprint) {
      await client.query("SELECT pg_advisory_xact_lock(hashtextextended($1, 0))", [`${args.riderId}:${args.fingerprint}`]);
      const existing = await client.query<{ id: string }>(
        `SELECT id FROM ops_items
         WHERE rider_id = $1 AND claim_fingerprint = $2 AND item_type = $3 AND status = 'pending'
         ORDER BY created_at ASC LIMIT 1`,
        [args.riderId, args.fingerprint, args.type],
      );
      if (existing.rows[0]) {
        await client.query("COMMIT");
        return { id: existing.rows[0].id, created: false };
      }
    }
    const id = randomUUID();
    await client.query(
      `INSERT INTO ops_items (id, rider_id, item_type, amount_rupees, reason, status, claim, claim_fingerprint)
       VALUES ($1, $2, $3, $4, $5, 'pending', $6::jsonb, $7)`,
      [id, args.riderId, args.type, args.amount, args.reason, JSON.stringify(args.claim), args.fingerprint],
    );
    await client.query("COMMIT");
    return { id, created: true };
  } catch (error) {
    await client.query("ROLLBACK");
    throw error;
  } finally {
    client.release();
  }
}

async function hasPriorClaim(pool: Pool, riderId: string, fingerprint: string): Promise<boolean> {
  const result = await pool.query<{ found: boolean }>(
    `SELECT EXISTS (
       SELECT 1 FROM payment_records
       WHERE rider_id = $1 AND claim_fingerprint = $2
         AND lower(status) IN ('reserved', 'processing', 'succeeded', 'paid', 'completed')
       UNION ALL
       SELECT 1 FROM ops_items
       WHERE rider_id = $1 AND claim_fingerprint = $2
         AND item_type = 'approval' AND status IN ('pending', 'approved', 'resolved')
     ) AS found`,
    [riderId, fingerprint],
  );
  return result.rows[0]?.found ?? false;
}

async function recordClaimOccurrence(
  pool: Pool,
  riderId: string,
  fingerprint: string,
  messageId: string,
  claim: Record<string, unknown>,
): Promise<number> {
  const result = await pool.query<{ occurrence_count: number }>(
    `INSERT INTO claim_decisions (rider_id, claim_fingerprint, occurrence_count, last_message_id, latest_decision)
     VALUES ($1, $2, 1, $3, $4::jsonb)
     ON CONFLICT (rider_id, claim_fingerprint) DO UPDATE
       SET occurrence_count = claim_decisions.occurrence_count +
             CASE WHEN claim_decisions.last_message_id IS DISTINCT FROM EXCLUDED.last_message_id THEN 1 ELSE 0 END,
           last_message_id = EXCLUDED.last_message_id,
           latest_decision = EXCLUDED.latest_decision,
           last_seen_at = now()
     RETURNING occurrence_count`,
    [riderId, fingerprint, messageId, JSON.stringify(claim)],
  );
  return Number(result.rows[0]?.occurrence_count ?? 1);
}

async function updateClaimDecision(
  pool: Pool,
  riderId: string,
  fingerprint: string,
  claim: Record<string, unknown>,
): Promise<void> {
  await pool.query(
    `UPDATE claim_decisions
     SET latest_decision = $3::jsonb, last_seen_at = now()
     WHERE rider_id = $1 AND claim_fingerprint = $2`,
    [riderId, fingerprint, JSON.stringify(claim)],
  );
}

async function hasPaymentOnIstDate(pool: Pool, riderId: string, date: string): Promise<boolean> {
  const result = await pool.query<{ found: boolean }>(
    `SELECT EXISTS (
       SELECT 1 FROM payment_records
       WHERE rider_id = $1
         AND (created_at AT TIME ZONE 'Asia/Kolkata')::date = $2::date
         AND lower(status) = ANY($3::text[])
     ) AS found`,
    [riderId, date, ACTIVE_PAYMENT_STATUSES],
  );
  return result.rows[0]?.found ?? false;
}

async function hasOtherActiveSlot(pool: Pool, riderId: string, date: string, fingerprint: string): Promise<boolean> {
  const result = await pool.query<{ found: boolean }>(
    `SELECT EXISTS (
       SELECT 1 FROM automatic_payment_slots
       WHERE rider_id = $1 AND payout_date = $2::date
         AND claim_fingerprint <> $3 AND status IN ('reserved', 'consumed')
     ) AS found`,
    [riderId, date, fingerprint],
  );
  return result.rows[0]?.found ?? false;
}

async function reserveAutomaticSlot(
  pool: Pool,
  riderId: string,
  date: string,
  fingerprint: string,
  amount: number,
): Promise<boolean> {
  const result = await pool.query<{ claim_fingerprint: string }>(
    `INSERT INTO automatic_payment_slots (rider_id, payout_date, claim_fingerprint, amount_rupees, status)
     VALUES ($1, $2::date, $3, $4, 'reserved')
     ON CONFLICT (rider_id, payout_date) DO UPDATE
       SET claim_fingerprint = EXCLUDED.claim_fingerprint,
           amount_rupees = EXCLUDED.amount_rupees,
           status = 'reserved',
           created_at = now()
       WHERE automatic_payment_slots.status = 'released'
          OR automatic_payment_slots.claim_fingerprint = EXCLUDED.claim_fingerprint
     RETURNING claim_fingerprint`,
    [riderId, date, fingerprint, amount],
  );
  return result.rows[0]?.claim_fingerprint === fingerprint;
}

export async function decideClaimPaths(
  pool: Pool,
  riderId: string,
  outcomes: ClaimOutcome[],
  args: { messageId: string; identityMismatch: boolean },
): Promise<DecisionResult> {
  const events: DecisionEvent[] = [];
  if (args.identityMismatch) {
    const incidentFingerprint = createHash("sha256").update(`${riderId}:identity-mismatch:${args.messageId}`).digest("hex");
    const reason = "The message references a different rider identity; payout details were not checked.";
    const claim = {
      issue_id: null,
      fingerprint: incidentFingerprint,
      scope: null,
      status: "suspicious",
      decision_path: "suspicious_escalation",
      decision_reason: reason,
      verified_owed_rupees: 0,
      assessments: [],
      evidence: { identity_mismatch: true, message_id: args.messageId },
    };
    const opsItem = await createPendingOpsItem(pool, {
      riderId,
      type: "escalation",
      amount: null,
      reason,
      fingerprint: incidentFingerprint,
      claim,
    });
    events.push({
      type: "decision",
      name: "suspicious_claim_escalated",
      input: { message_id: args.messageId, rider_id: riderId },
      output: { ops_item_id: opsItem.id, created: opsItem.created, reason, verified_owed_rupees: 0 },
    });
    return {
      outcomes,
      events,
      identityMismatchReply: "I can help only with the rider account linked to this number. I have sent this identity mismatch to the operations team for review.",
    };
  }

  // This cap follows the actual processing/payment day, not a rider-supplied or backdated received_at.
  const paymentIstDate = istDate(new Date());
  const paymentAlreadyMadeToday = await hasPaymentOnIstDate(pool, riderId, paymentIstDate);
  const decided: ClaimOutcome[] = [];

  for (const source of outcomes) {
    const item: ClaimOutcome = { ...source };
    const fullyAssessed = item.status === "verified_shortfall" || item.status === "no_shortfall";
    const verifiedOwed = fullyAssessed
      ? Math.max(0, item.assessments.reduce((sum, assessment) => sum + assessment.shortfallRupees, 0))
      : 0;
    item.verified_owed_rupees = verifiedOwed;
    const fingerprint = fingerprintFor(riderId, item);
    item.claim_fingerprint = fingerprint;
    const occurrenceCount = item.status === "needs_information" || item.status === "unclear" || item.status === "suspicious"
      ? 0
      : await recordClaimOccurrence(pool, riderId, fingerprint, args.messageId, claimEvidence(item, fingerprint));

    if (item.status === "needs_information") {
      item.decision_path = "needs_information";
      item.decision_reason = "Required claim details are missing.";
    } else if (item.status === "suspicious") {
      item.decision_path = "suspicious_escalation";
      item.decision_reason = item.reason;
      const opsItem = await createPendingOpsItem(pool, {
        riderId, type: "escalation", amount: null, reason: `Possible account or trip ownership mismatch: ${item.reason}`,
        fingerprint, claim: claimEvidence(item, fingerprint),
      });
      item.ops_item_id = opsItem.id;
      item.reply = "The trip details do not match the rider account linked to this number. I have sent the case to the operations team to review.";
    } else if (item.status === "unclear") {
      item.decision_path = "unclear_escalation";
      item.decision_reason = item.reason;
